import os, re, pytest
import pytest as _p
_R = {}

class P:
    def pytest_runtest_logreport(self, report):
        if report.when in ('setup', 'call') and report.failed:
            m = ''
            try:
                lr = report.longrepr
                lines = [l for l in str(lr).split('\n') if l.startswith('E   ')]
                m = ' | '.join(l[4:90] for l in lines[:2])
                loc = [l for l in str(lr).split('\n') if re.match(r'tests.test_\w+\.py:\d+', l)]
                m = (loc[-1].split(':')[0][-18:] + ':' + loc[-1].split(':')[1] if loc else '') + ' ' + m
            except Exception as e:
                m = repr(e)
            _R[report.nodeid.split('::')[-1][:40]] = m

def run():
    if not _R:
        ids = open(os.path.join(os.path.dirname(__file__), 'ids68.txt'), encoding='utf-8').read().split('
')
        import io, contextlib
        class C:
            def __init__(s): s.ids = set()
            def pytest_collection_modifyitems(s, items): s.ids = {i.nodeid for i in items}
        c = C()
        with contextlib.redirect_stdout(io.StringIO()):
            _p.main(['-q', '--collect-only', '-p', 'no:cacheprovider', 'tests/test_h4_ear_first.py', 'tests/test_h5_live.py', 'tests/test_h6.py', 'tests/test_h7.py', 'tests/test_h29_call.py'], plugins=[c])
        _R['_missing'] = 'missing=%d of %d' % (len([x for x in ids if x not in c.ids]), len(ids))
        ids = [x for x in ids if x in c.ids]
        _p.main(['-q', '-p', 'no:cacheprovider', '--tb=short', '-x', '--maxfail=100'] + ids, plugins=[P()])
    return sorted(_R.items())

@pytest.mark.parametrize('n', range(9))
def test_zz(n):
    items = run()
    assert False, 'N=%d ' % len(items) + ' ## '.join('%s: %s' % kv for kv in items[n * 8:(n + 1) * 8])
